insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','행정사무감사 반복 지적사항 TOP 50','<div class="box" style="margin-bottom:16px"><b>게시판 분석 자료</b> · 작성자 관리자 · 게시일 2026-09-12<br><a href="https://grilu.kr/archive/documents/report-audit.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문 전문 보기</a></div><p style="line-height:1.8;color:#444"> 경기도의회 행정사무감사 회의록 31건(제4대 1995년 ~ 제11대 2025년, 경기연구원 피감 회의)에서  여러 회차에 걸쳐 반복 지적된 사항 을 50개 주제로 묶어 정리했습니다. 언급 횟수는 &#x27;지적·문제·개선·미흡·필요&#x27; 등 지적성 표현이 들어간 문장 가운데 해당 주제가 나온 문장 수이며, 대표 회의자료를 누르면 해당 낱말이 형광 표시된 회의록 전문이 열립니다.     순위  지적사항 내용  근거(게시판 자료) · 언급 횟수  대표 회의자료(링크)      1  연구성과 홍보·확산 부족 — 연구결과가 도민·도정에 충분히 알려지지 않음  홍보 강화, 보도자료·언론 활용 요구  24회차  감사 /  101회  언급   2006년 기획위원회   (15회)   2008년 기획위원회   (11회)   1995년 기획위원회   (9회)   2014년 기획재정위원회   (6회)   외 20회차     2  직원 복지·근무환경 개선 요구 — 타 기관 대비 열악한 근무여건  복지·근무환경 관련 지적 반복  26회차  감사 /  89회  언급   2012년 기획위원회   (17회)   2011년 기획위원회   (12회)   2015년 기획재정위원회   (7회)   201…</p>','관리자',false,'{"legacy_id": "gw-report-audit", "page": "archive/documents/report-audit.html", "files": [], "source": "게시판 분석"}'::jsonb,'2026-09-12'::date,'2026-09-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-report-audit');
