insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','여러 직군에 공통으로 해당되는 요청사항 TOP 20','<div class="box" style="margin-bottom:16px"><b>게시판 분석 자료</b> · 작성자 관리자 · 게시일 2026-09-12<br><a href="https://grilu.kr/archive/documents/report-demands-common.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문 전문 보기</a></div><p style="line-height:1.8;color:#444"> 홈페이지 게시판(노사협의회 공고·회의록 73건, 단체교섭·단체협약 10건, 심의위원회 19건, 노동이사 활동보고 14건, 행정사무감사 회의록 31건)에 실린 노측 건의·요구 사항을 직군별로 모아 정리했습니다. 빈도(반복 제기 횟수)와 최근성(2023년 이후 협의회 안건)을 우선해 순위를 매겼습니다. 오른쪽 열의  건수/횟수 는 게시판 전체 자료(본문+첨부 전문)에서 해당 주제가 언급된 글 수와 문장 수이며, 대표 자료를 누르면 해당 문장이 형광 표시된 원문이 열립니다.  여러 직군에 공통으로 해당되는 요청사항 TOP 20  연구위원급(박사급)·연구원급(공무직)·행정직군 모두에게 혜택이 되는 항목만 골라 정리했습니다.     순위  요구사항  근거 및 언급 횟수  대표 회의자료(링크)      1  특별휴가 제도 개선 (항목 확대, 복무시스템 개선 후 조속 시행)  2026.5·7 협의회 공통 안건  13건  자료 /  71회  언급   2025.02 25-1차 심의위원회 상정(안) 게시 및 직원 …   (18회)   2024.06 24-7차 심의위원회 상정(안) 게시 및 직원 …   (10회)   2020.04 취업규칙 일부 개정규칙 공포   (9회)   …</p>','관리자',false,'{"legacy_id": "gw-report-demands-common", "page": "archive/documents/report-demands-common.html", "files": [], "source": "게시판 분석"}'::jsonb,'2026-09-12'::date,'2026-09-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-report-demands-common');
