insert into public.posts (board,title,content,author_name,is_notice,attachments,created_at,updated_at) select 'documents','우리 연구원의 문제점-개선안 Top 20','<div class="box" style="margin-bottom:16px"><b>게시판 분석 자료</b> · 작성자 관리자 · 게시일 2026-09-12<br><a href="https://grilu.kr/archive/documents/report-issues.html" style="color:var(--primary);text-decoration:underline;font-weight:700">▶ 본문 전문 보기</a></div><p style="line-height:1.8;color:#444"> 게시판에 실린 노사협의회 회의록(2009~2026), 단체교섭·단체협약 공고, 심의위원회 상정안, 노동이사 활동보고, 경기도의회 행정사무감사 회의록에서 반복적으로 드러난 연구원의 문제점과 그에 대한 개선안을 20개로 정리했습니다. 순위는 제기 빈도와 최근 3년간 논의 지속 여부를 기준으로 했습니다.     순위  문제점  개선안  근거 및 언급 횟수  대표 회의자료(링크)      1  타 연구기관 대비 낮은 처우와 높은 이직률 (행감 2021~2025년 연속 지적)  직군별 보수 실태 비교 공개 → 중장기 인력운영계획에 처우개선 로드맵·재원 명시, 이직 원인 조사 정례화   33건  자료 /  110회  언급   2020.11 행감 [2020.11.09. 월요일]    (13회)   2026.01 2025년 하반기 경기연구원 노동이사 활동 보고   (9회)   2025.11 행감 [2025.11.11. 화요일]    (8회)   2023.07 23-11차 심의위원회 상정(안) 게시 및 직원…   (7회)   외 29건     2  공무직 직급·보수체계 미비 (승진 경로 없음, 32등급 조견표 한계)  연구원 가·나급/선임연구원 직급 신설, 승진가급·근속수…</p>','관리자',false,'{"legacy_id": "gw-report-issues", "page": "archive/documents/report-issues.html", "files": [], "source": "게시판 분석"}'::jsonb,'2026-09-12'::date,'2026-09-12'::date where not exists (select 1 from public.posts where attachments->>'legacy_id' = 'gw-report-issues');
